    'modules.newsLearnMore': 'The News module publishes articles to the public homepage. Head-office authors write for the whole church; a parish author writes for their own Atbiya and their posts carry the parish name. Save a draft while you work, then publish when it is ready.',
    'modules.membersLearnMore': 'The Members module is your church directory. Add members with their personal contact, jurisdiction (hierarchy level, region, zone), and ministry roles. Use search, sort and filters to find people quickly, and export the directory when permitted.',
    'modules.plansLearnMore': 'The Plans module organises ministry plans across all levels. Create a plan with a name, a period (weekly, monthly or annually) and details, then track progress through reports submitted against it.',
    'modules.reportsLearnMore': 'The Reports module is where units submit and review work reports. Pick the plan a report belongs to, choose the submission type, describe the work done and the results, and leaders can add professional feedback.',
    'modules.announcementsLearnMore': 'Post church-wide announcements here. Members are notified on web and mobile. Optionally set an expiry date so time-sensitive notices disappear automatically.',
    'modules.meetingsLearnMore': 'Schedule and coordinate meetings and events. Choose who is notified \\u2014 a whole diocese, one congregation, or only particular roles \\u2014 and upcoming/past meetings are tracked automatically.',
    'modules.financeLearnMore': 'Track income, expenses, budgets and financial reports. Record transactions, set monthly budgets, and generate reports for accountability.',
    'modules.hrLearnMore': 'Manage church employees: positions, departments, employment type, salary and status. Use it as the HR record for staff and contractors.',
    'modules.inventoryLearnMore': 'Track church assets, equipment and property \\u2014 quantity, location, condition, value and assignment. Monitor what the church owns and its state.',
    'modules.teachingsLearnMore': 'Publish sermons and Bible studies. Each sermon has a speaker, service type, summary and full content for members to read.',
    'modules.documentsLearnMore': 'Browse and manage official church documents in folders. Upload files, create folders, and open documents \\u2014 access follows your permissions.',
    'modules.hierarchyLearnMore': 'The official organizational structure of the church per the bylaws \\u2014 from the Synod down to local parishes \\u2014 with each body\\\'s roles and responsibilities.',
    'modules.missionaryLearnMore': 'Apply for missionary service and submit field reports. Choose your missionary type and desired location, and track applications and impact.',
    'modules.volunteerLearnMore': 'Choose the ministries you would like to serve in. Your preferences are saved to your profile so coordinators can reach you.',
    'modules.strategicPlanLearnMore': 'Track long-term vision goals and strategic milestones, with progress against targets over time.',
    'modules.churchRulesLearnMore': 'Browse the church\\\'s canonical guidelines, prohibitions, obligations and administrative rules.',
    'modules.higeDenbLearnMore': 'Access the church governance rules (Hige Denb) covering structure, reporting, conduct and communication protocol.',
