    'pages.higeDenbGovernanceTitle': 'Church Governance Structure',
    'pages.higeDenbGovernanceBody': 'The Ethiopian Orthodox Tewahedo Church follows a hierarchical structure starting from Sinodos at the highest level, followed by KuamiSinodos (9 units), Memriya (7 members), Zone, Atbiya (individual churches), EnkesekaseMaikel, and HiyawanMahderat at the base level.',
    'pages.higeDenbReportingTitle': 'Reporting Requirements',
    'pages.higeDenbReportingBody': 'All Memriya members and higher levels must submit regular reports on church activities, including attendance, financial matters, and ministry progress. Reports should be submitted according to the designated frequency: weekly, monthly, or yearly.',
    'pages.higeDenbConductTitle': 'Ministry Conduct',
    'pages.higeDenbConductBody': 'All church members serving in ministry roles must uphold the highest standards of spiritual conduct, maintain regular attendance at services, and actively participate in their assigned ministry areas. Sunday School teachers, youth leaders, and other ministry workers must complete appropriate training.',
    'pages.higeDenbCommunicationTitle': 'Communication Protocol',
    'pages.higeDenbCommunicationBody': 'Official announcements can only be made by Memriya level and above. All communications must follow the established chain of command. Urgent matters should be escalated through proper channels to ensure timely response and appropriate action.',
