    'structure.sinodosName': 'Synod of Ahaw',
    'structure.sinodosRole1': 'Supreme general assembly and final decision-making body of the church.',
    'structure.sinodosRole2': 'Approves the appointment of the General Manager and institution managers.',
    'structure.sinodosRole3': 'Decides the policy direction of the church.',
    'structure.sinodosRole4': 'Approves new members and removes membership; full authority to ordain priests.',
    'structure.sinodosRole5': 'Amends the bylaws and other regulations as the church grows.',
    'structure.sinodosRole6': 'Approves the strategic plan; reviews service and performance against it.',
    'structure.sinodosRole7': 'Reviews and approves the annual work and audit reports.',
    'structure.sinodosRole8': 'Meets in regular session twice a year, plus emergency sessions.',
    'structure.chairmanPriestName': 'Chairman Priest',
    'structure.chairmanPriestRole1': 'Serves as chairman of both the Synod and the Standing Synod.',
    'structure.chairmanPriestRole2': 'Delivers opening/closing addresses and exhortation at church programs.',
    'structure.chairmanPriestRole3': 'Oversees the life and service of Synod members.',
    'structure.chairmanPriestRole4': 'Ensures Synod directives, policies and decisions are properly implemented.',
    'structure.chairmanPriestRole5': 'Safeguards the foundational faith and represents the church externally.',
    'structure.synodSecretaryName': 'Synod Secretary',
    'structure.synodSecretaryRole1': 'Prepares agendas for the Synod and Standing Synod with the chairman and manager.',
    'structure.synodSecretaryRole2': 'Records, reads, ratifies and archives meeting minutes.',
    'structure.synodSecretaryRole3': 'Transmits ratified decisions to the relevant bodies.',
    'structure.synodSecretaryRole4': 'Receives and routes correspondence; calls regular and emergency meetings.',
    'structure.auditCommitteeName': 'Audit & Work Inspection Committee',
    'structure.auditCommitteeRole1': 'Audits the accuracy of the church\'s finance and property administration.',
    'structure.auditCommitteeRole2': 'Verifies operations are carried out per the bylaws, Synod decisions and approved plan.',
    'structure.auditCommitteeRole3': 'Confirms the existence and condition of church assets.',
    'structure.auditCommitteeRole4': 'Accountable directly to the Synod.',
    'structure.standingSynodName': 'Standing Synod',
