    'modules.fldMissionaryMissionaryType': 'የሚስዮን አገልግሎት ዓይነት',
    'modules.fldMissionaryDesiredLocation': 'የሚፈለግ ቦታ',
    'modules.fldMissionaryWhyServe': 'ለምን ማገልገል ይፈልጋሉ?',
    'modules.newsLearnMore': 'የዜና ክፍል ጽሑፎችን ወደ ይፋዊ ዋና ገፅ ያሳትማል። የጠቅላይ ጽ/ቤት ጸሐፊዎች ለመላው ቤተ ክርስቲያን ይጽፋሉ፤ የአጥቢያ ጸሐፊ ግን ለራሱ አጥቢያ ይጽፋል፤ ጽሑፎቹም የአጥቢያውን ስም ይይዛሉ። ሲሠሩ ረቂቅ ያስቀምጡ፤ ሲዘጋጅ ያሳትሙ።',
    'modules.membersLearnMore': 'የአባላት ክፍል የቤተ ክርስቲያንዎ ማውጫ ነው። አባላትን ከግል አድራሻቸው፣ ከአገልግሎት ክልላቸው (የእርከን ደረጃ፣ ክልል፣ ሀገረ ስብከት) እና ከአገልግሎት ኃላፊነታቸው ጋር ይጨምሩ። ሰዎችን በፍጥነት ለማግኘት ፍለጋን፣ ደርድርንና ማጣሪያዎችን ይጠቀሙ፤ ሲፈቀድም ማውጫውን ያውጡ።',
    'modules.plansLearnMore': 'የዕቅድ ክፍል የአገልግሎት ዕቅዶችን በሁሉም እርከኖች ያደራጃል። ዕቅድን በስም፣ በጊዜ ገደብ (ሳምንታዊ፣ ወርኃዊ ወይም ዓመታዊ) እና በዝርዝር ይፍጠሩ፤ ከዚያም በእሱ ላይ በሚቀርቡ ሪፖርቶች ሂደቱን ይከታተሉ።',
    'modules.reportsLearnMore': 'የሪፖርት ክፍል ክፍሎች የሥራ ሪፖርት የሚያቀርቡበትና የሚገመገምበት ነው። ሪፖርቱ የሚመለከተውን ዕቅድ ይምረጡ፣ የማስገቢያ ዓይነቱን ይወስኑ፣ የተሠራውን ሥራና ውጤቱን ይግለጹ፤ አመራሮችም ሙያዊ አስተያየት መጨመር ይችላሉ።',
    'modules.announcementsLearnMore': 'ቤተ ክርስቲያንን አቀፍ ማስታወቂያዎችን እዚህ ይለጥፉ። አባላት በድረ ገጽና በሞባይል ማሳወቂያ ይደርሳቸዋል። አስፈላጊ ከሆነ ጊዜ ገደብ ያስቀምጡ፤ ጊዜያዊ ማስታወቂያዎች በራሳቸው ይጠፋሉ።',
    'modules.meetingsLearnMore': 'ስብሰባዎችንና ዝግጅቶችን ይያዙ፤ ያስተባብሩ። ማን እንደሚያውቅ ይምረጡ — መላው ሀገረ ስብከት፣ አንድ አጥቢያ ወይም የተወሰኑ ኃላፊነቶች ብቻ — የሚመጡና ያለፉ ስብሰባዎችም በራሳቸው ይመዘገባሉ።',
    'modules.financeLearnMore': 'ገቢን፣ ወጪን፣ በጀትንና የገንዘብ ሪፖርቶችን ይከታተሉ። ግብይቶችን ይመዝግቡ፣ ወርኃዊ በጀት ያስቀምጡ፤ ለተጠያቂነትም ሪፖርቶችን ያዘጋጁ።',
    'modules.hrLearnMore': 'የቤተ ክርስቲያኒቱን ሠራተኞች ያስተዳድሩ፦ የሥራ መደብ፣ መምሪያ፣ የቅጥር ዓይነት፣ ደመወዝና ሁኔታ። ለሠራተኞችና ለውል ሠራተኞች እንደ የሰው ሀብት መዝገብ ይጠቀሙበት።',
    'modules.inventoryLearnMore': 'የቤተ ክርስቲያኒቱን ንብረት፣ መሣሪያና ሕንፃ ይከታተሉ — ብዛት፣ ቦታ፣ ደረጃ፣ ግምትና ምደባ። ቤተ ክርስቲያኒቱ ያላትን ንብረትና ያለበትን ሁኔታ ይቆጣጠሩ።',
    'modules.teachingsLearnMore': 'ስብከቶችንና የመጽሐፍ ቅዱስ ጥናቶችን ያሳትሙ። እያንዳንዱ ስብከት አስተማሪ፣ የአገልግሎት ዓይነት፣ ማጠቃለያና አባላት የሚያነቡት ሙሉ ይዘት አለው።',
    'modules.documentsLearnMore': 'ይፋዊ የቤተ ክርስቲያን ሰነዶችን በአቃፊዎች ይመልከቱና ያስተዳድሩ። ፋይሎችን ይጫኑ፣ አቃፊ ይፍጠሩ፣ ሰነዶችን ይክፈቱ — መዳረሻው በፈቃድዎ ልክ ነው።',
    'modules.hierarchyLearnMore': 'በመተዳደሪያ ደንቡ መሠረት ያለው ይፋዊ የቤተ ክርስቲያኒቱ ተቋማዊ መዋቅር — ከሲኖዶስ እስከ አጥቢያ አብያተ ክርስቲያናት — ከየአካሉ ሥልጣንና ተግባር ጋር።',
    'modules.missionaryLearnMore': 'ለሚስዮን አገልግሎት ያመልክቱ፤ የመስክ ሪፖርቶችንም ያስገቡ። የአገልግሎትዎን ዓይነትና የሚፈልጉትን ቦታ ይምረጡ፤ ማመልከቻዎችንና ውጤቱን ይከታተሉ።',
    'modules.volunteerLearnMore': 'ማገልገል የሚፈልጓቸውን የአገልግሎት ዘርፎች ይምረጡ። ምርጫዎ በመገለጫዎ ላይ ስለሚቀመጥ አስተባባሪዎች ሊያገኙዎት ይችላሉ።',
    'modules.strategicPlanLearnMore': 'የረጅም ጊዜ የራእይ ግቦችንና ስትራቴጂያዊ ምዕራፎችን ይከታተሉ፤ ከዒላማው አንጻር ያለውን ሂደትም በጊዜ ሂደት ይመልከቱ።',
    'modules.churchRulesLearnMore': 'የቤተ ክርስቲያኒቱን ቀኖናዊ መመሪያዎች፣ ክልከላዎች፣ ግዴታዎችና የአስተዳደር ደንቦች ይመልከቱ።',
    'modules.higeDenbLearnMore': 'መዋቅርን፣ ሪፖርትን፣ ሥነ ምግባርንና የመገናኛ ሥርዓትን የሚሸፍኑ የቤተ ክርስቲያኒቱን የአስተዳደር ደንቦች (ሕገ ደንብ) ይመልከቱ።',
