    'pages.higeDenbGovernanceBody': 'የኢትዮጵያ ኦርቶዶክስ ተዋሕዶ ቤተ ክርስቲያን ከሲኖዶስ ጀምሮ በእርከን የተደራጀ መዋቅር ትከተላለች፤ ቀጥሎም ቋሚ ሲኖዶስ (9 ክፍሎች)፣ መምሪያ (7 አባላት)፣ ሀገረ ስብከት፣ አጥቢያ (የየራሳቸው አብያተ ክርስቲያናት)፣ እንቀጸ ካሴ ሚካኤልና በመሠረቱ ደረጃ ሕያዋን ማኅደራት ይገኛሉ።',
