    'pages.higeDenbReportingBody': 'የመምሪያ አባላትና ከዚያ በላይ ያሉ እርከኖች ሁሉ ስለ ቤተ ክርስቲያኒቱ ተግባራት — ተሳትፎን፣ የገንዘብ ጉዳዮችንና የአገልግሎት ሂደትን ጨምሮ — መደበኛ ሪፖርት ማቅረብ አለባቸው። ሪፖርቶች በተወሰነው ድግግሞሽ መሠረት በሳምንት፣ በወር ወይም በዓመት መቅረብ አለባቸው።',
    'pages.higeDenbConductTitle': 'የአገልግሎት ሥነ ምግባር',
    'pages.higeDenbConductBody': 'በአገልግሎት ኃላፊነት ላይ ያሉ የቤተ ክርስቲያኒቱ አባላት ሁሉ ከፍተኛውን መንፈሳዊ ሥነ ምግባር መጠበቅ፣ በአገልግሎት ላይ በመደበኛነት መገኘትና በተመደቡበት የአገልግሎት ዘርፍ በንቃት መሳተፍ አለባቸው። የሰንበት ትምህርት ቤት አስተማሪዎች፣ የወጣቶች መሪዎችና ሌሎች የአገልግሎት ሠራተኞች ተገቢውን ሥልጠና ማጠናቀቅ አለባቸው።',
    'pages.higeDenbCommunicationTitle': 'የመገናኛ ሥርዓት',
    'pages.higeDenbCommunicationBody': 'ይፋዊ ማስታወቂያ ማውጣት የሚችሉት ከመምሪያ ደረጃና ከዚያ በላይ ያሉ ብቻ ናቸው። ሁሉም ግንኙነቶች የተዘረጋውን የትእዛዝ ሰንሰለት መከተል አለባቸው። አስቸኳይ ጉዳዮች ወቅታዊ ምላሽና ተገቢ እርምጃ እንዲያገኙ በተገቢው መስመር ወደ ላይ መተላለፍ አለባቸው።',
    'pages.goalProgressUntracked': 'የዚህ ግብ ክንውን እስካሁን አልተመዘገበም።',
