    'structure.sinodosRole5': 'ቤተ ክርስቲያኒቱ ስታድግ መተዳደሪያ ደንቡንና ሌሎች ደንቦችን ያሻሽላል።',
    'structure.sinodosRole6': 'ስትራቴጂያዊ ዕቅዱን ያጸድቃል፤ አገልግሎትንና አፈጻጸምን በእሱ ልክ ይገመግማል።',
    'structure.sinodosRole7': 'ዓመታዊ የሥራና የኦዲት ሪፖርቶችን ይገመግማል፤ ያጸድቃል።',
    'structure.sinodosRole8': 'በዓመት ሁለት ጊዜ መደበኛ ስብሰባ ያደርጋል፤ ከዚህ በተጨማሪ አስቸኳይ ስብሰባዎችን ያካሂዳል።',
    'structure.chairmanPriestName': 'ሰብሳቢ ቄስ',
    'structure.chairmanPriestRole1': 'የሲኖዶሱም የቋሚ ሲኖዶሱም ሰብሳቢ ሆኖ ያገለግላል።',
    'structure.chairmanPriestRole2': 'በቤተ ክርስቲያኒቱ መርሐ ግብራት ላይ የመክፈቻና የመዝጊያ ንግግርና ምዕዳን ያቀርባል።',
    'structure.chairmanPriestRole3': 'የሲኖዶስ አባላትን ኑሮና አገልግሎት ይቆጣጠራል።',
    'structure.chairmanPriestRole4': 'የሲኖዶሱ መመሪያዎች፣ ፖሊሲዎችና ውሳኔዎች በአግባቡ መፈጸማቸውን ያረጋግጣል።',
    'structure.chairmanPriestRole5': 'የመሠረታዊ እምነቱን ጠባቂ ሆኖ ቤተ ክርስቲያኒቱን በውጭ ይወክላል።',
    'structure.synodSecretaryName': 'የሲኖዶስ ጸሐፊ',
    'structure.synodSecretaryRole1': 'ከሰብሳቢውና ከሥራ አስኪያጁ ጋር ሆኖ ለሲኖዶሱና ለቋሚ ሲኖዶሱ አጀንዳ ያዘጋጃል።',
    'structure.synodSecretaryRole2': 'የስብሰባ ቃለ ጉባኤዎችን ይመዘግባል፣ ያነባል፣ ያጸድቃል፤ በማኅደር ያስቀምጣል።',
    'structure.synodSecretaryRole3': 'የጸደቁ ውሳኔዎችን ለሚመለከታቸው አካላት ያስተላልፋል።',
    'structure.synodSecretaryRole4': 'ደብዳቤዎችን ተቀብሎ ያደርሳል፤ መደበኛና አስቸኳይ ስብሰባዎችን ይጠራል።',
    'structure.auditCommitteeName': 'ኦዲትና የሥራ ምርመራ ኮሚቴ',
    'structure.auditCommitteeRole1': 'የቤተ ክርስቲያኒቱ የገንዘብና የንብረት አስተዳደር ትክክለኛነት ኦዲት ያደርጋል።',
    'structure.auditCommitteeRole2': 'ሥራዎች በመተዳደሪያ ደንቡ፣ በሲኖዶስ ውሳኔዎችና በጸደቀው ዕቅድ መሠረት መከናወናቸውን ያረጋግጣል።',
    'structure.auditCommitteeRole3': 'የቤተ ክርስቲያኒቱ ንብረቶች መኖራቸውንና ያሉበትን ሁኔታ ያረጋግጣል።',
    'structure.auditCommitteeRole4': 'በቀጥታ ለሲኖዶሱ ተጠሪ ነው።',
    'structure.standingSynodName': 'ቋሚ ሲኖዶስ',
    'structure.standingSynodRole1': 'ከሲኖዶሱ የተመረጠ ዘጠኝ አባላት ያሉት የሥራ አስፈጻሚ አመራር ጉባኤ ነው።',
    'structure.standingSynodRole2': 'የሲኖዶስ ውሳኔዎች እንዲፈጸሙ ሥራ አስፈጻሚውንና ተቋማቱን ይመራል፤ በቅርበት ይከታተላል።',
    'structure.standingSynodRole3': 'ለጠቅላይ ሥራ አስኪያጁና ለተቋማት አመራሮች መመሪያ ይሰጣል፤ አፈጻጸሙን ይቆጣጠራል።',
    'structure.standingSynodRole4': 'የሀገረ ስብከት ጽ/ቤት ሥራ አስኪያጆችን ለሹመት ያቀርባል።',
    'structure.standingSynodRole5': 'ለሲኖዶሱ ተጠሪ ሆኖ ይሰበሰባል፤ የስትራቴጂያዊ አመራር ሚና ይጫወታል።',
    'structure.theologicalCouncilName': 'የነገረ ሃይማኖት መማክርት ጉባኤ',
    'structure.theologicalCouncilRole1': 'በነገረ ሃይማኖትና በእምነት ጉዳዮች ላይ ለቋሚ ሲኖዶሱ ምክር ይሰጣል።',
    'structure.theologicalCouncilRole2': 'ትምህርቶች፣ መጻሕፍትና የእምነት መግለጫዎች ከሃይማኖት አንጻር ትክክል መሆናቸውን ይገመግማል።',
