    'structure.generalOfficeRole2': 'በአስተዳደር ጉባኤ፣ በመምሪያዎችና በተለያዩ ክፍሎች የተደራጀ ነው።',
    'structure.generalManagerName': 'ጠቅላይ ሥራ አስኪያጅ',
    'structure.generalManagerRole1': 'በሲኖዶሱ ይሾማል፤ ለቋሚ ሲኖዶሱ ተጠሪ ነው።',
    'structure.generalManagerRole2': 'የቤተ ክርስቲያኒቱን አጠቃላይ አገልግሎትና አስተዳደር ዕለታዊ አፈጻጸም ይመራል።',
    'structure.generalManagerRole3': 'የሲኖዶስና የቋሚ ሲኖዶስ ውሳኔዎችን በመዋቅሩ ሁሉ ያስፈጽማል።',
    'structure.deputyManagerName': 'ምክትል ሥራ አስኪያጅ',
