    'structure.adminCouncilName': 'የጠቅላይ ጽ/ቤት አስተዳደር ጉባኤ',
    'structure.adminCouncilRole1': 'በጠቅላይ ሥራ አስኪያጁ የሚመራ ሲሆን ምክትሉ ጸሐፊ ነው፤ የመምሪያ ኃላፊዎች አባላት ናቸው።',
    'structure.adminCouncilRole2': 'የአስተዳደር ውሳኔዎችን ይሰጣል፤ የአፈጻጸም አቅምን ይገመግማል።',
    'structure.adminCouncilRole3': 'ለመምሪያ አገልግሎቶች ስትራቴጂያዊ አቅጣጫ ያስቀምጣል፤ የሥራና የገንዘብ ዕቅዶችን ገምግሞ ያጸድቃል።',
